/* Exact, bounded sums of rational multiples of real square roots.
   Unsupported expressions return invalid; never reconstruct from a decimal. */
#define SYMBOL_TERMS 8
typedef struct{Rational c;int64_t rad;} RadicalTerm;
typedef struct{int n;RadicalTerm t[SYMBOL_TERMS];} Symbolic;
static Symbolic symbolicAns={0},symbolicResult={.n=-1};
static Symbolic sinvalid(void){return (Symbolic){.n=-1};}
static Symbolic srat(Rational a){if(!a.d)return sinvalid();Symbolic s={0};if(a.n){s.n=1;s.t[0]=(RadicalTerm){a,1};}return s;}
static Rational srational(Symbolic a){return a.n==0?rat(0,1):a.n==1&&a.t[0].rad==1?a.t[0].c:(Rational){0,0};}
static int saddTerm(Symbolic*s,Rational c,int64_t rad){if(s->n<0||!c.d||rad<1||rad>1000000000000LL){s->n=-1;return 0;}if(!c.n)return 1;int at=0;while(at<s->n&&s->t[at].rad<rad)at++;if(at<s->n&&s->t[at].rad==rad){c=rop(s->t[at].c,c,'+');if(!c.d){s->n=-1;return 0;}if(!c.n){memmove(s->t+at,s->t+at+1,(s->n-at-1)*sizeof(*s->t));s->n--;return 1;}s->t[at].c=c;return 1;}if(s->n>=SYMBOL_TERMS){s->n=-1;return 0;}memmove(s->t+at+1,s->t+at,(s->n-at)*sizeof(*s->t));s->t[at]=(RadicalTerm){c,rad};s->n++;return 1;}
static Symbolic sadd(Symbolic a,Symbolic b,int sub){if(a.n<0||b.n<0)return sinvalid();for(int i=0;i<b.n;i++){Rational c=b.t[i].c;if(sub)c.n=-c.n;if(!saddTerm(&a,c,b.t[i].rad))return sinvalid();}return a;}
static Symbolic smul(Symbolic a,Symbolic b){if(a.n<0||b.n<0)return sinvalid();Symbolic s={0};for(int i=0;i<a.n;i++)for(int j=0;j<b.n;j++){int64_t g=(int64_t)rgcd(a.t[i].rad,b.t[j].rad);__int128 rad=(__int128)(a.t[i].rad/g)*(b.t[j].rad/g);if(rad>1000000000000LL)return sinvalid();Rational c=rop(rop(a.t[i].c,b.t[j].c,'*'),rat(g,1),'*');if(!saddTerm(&s,c,(int64_t)rad))return sinvalid();}return s;}
static Symbolic sscale(Symbolic a,Rational b){if(a.n<0||!b.d)return sinvalid();for(int i=0;i<a.n;i++){a.t[i].c=rop(a.t[i].c,b,'*');if(!a.t[i].c.d)return sinvalid();}if(!b.n)a.n=0;return a;}
static Symbolic sdivide(Symbolic a,Symbolic b){if(a.n<0||b.n<=0||b.n>2)return sinvalid();Symbolic conjugate=b;if(b.n==2)conjugate.t[1].c.n=-conjugate.t[1].c.n;Rational denominator=srational(smul(b,conjugate));if(!denominator.d||!denominator.n)return sinvalid();return sscale(smul(a,conjugate),rat(denominator.d,denominator.n));}
static int squareParts(int64_t value,int64_t*out,int64_t*inside,int*budget){*out=1;*inside=1;if(value<1)return 0;int64_t square=llround(sqrt((double)value));if(square*square==value){*out=square;return 1;}for(int64_t p=2;p<=value/p;p=p==2?3:p+2){if(--*budget<0)return 0;int count=0;while(value%p==0){value/=p;count++;}for(int k=0;k<count/2;k++)*out*=p;if(count&1)*inside*=p;}*inside*=value;return 1;}
static Symbolic ssqrt(Symbolic a,int*budget){Rational r=srational(a);if(!r.d||r.n<0)return sinvalid();if(!r.n)return srat(r);int64_t an,ar,bn,br;if(!squareParts(r.n,&an,&ar,budget)||!squareParts(r.d,&bn,&br,budget))return sinvalid();__int128 rad=(__int128)ar*br;if(rad>1000000000000LL)return sinvalid();Symbolic s={0};if(!saddTerm(&s,rat(an,(__int128)bn*br),(int64_t)rad))return sinvalid();return s;}
typedef struct{const char*p;int depth,error,budget;Symbolic previous;} SParser;
static void sspace(SParser*p){while(isspace((unsigned char)*p->p))p->p++;}
static Symbolic ssum(SParser*);
static Symbolic satom(SParser*p){sspace(p);if(++p->depth>64){p->error=1;p->depth--;return sinvalid();}Symbolic a=sinvalid();if(*p->p=='('){p->p++;a=ssum(p);sspace(p);if(*p->p==')')p->p++;else p->error=1;}else if(isdigit((unsigned char)*p->p)||*p->p=='.'){RParser r={.p=p->p};Rational v=ratom(&r);p->p=r.p;if(r.error)p->error=1;a=srat(v);}else if(isalpha((unsigned char)*p->p)){char name[24];int n=0;while(isalpha((unsigned char)*p->p)){if(n<23)name[n++]=tolower((unsigned char)*p->p);p->p++;}name[n]=0;if(!strcmp(name,"ans"))a=p->previous;else{sspace(p);if(*p->p!='(')p->error=1;else{p->p++;a=ssum(p);sspace(p);if(*p->p==')')p->p++;else p->error=1;if(!strcmp(name,"sqrt"))a=ssqrt(a,&p->budget);else if(!strcmp(name,"abs")&&a.n<=1&&a.n>=0){if(a.n&&a.t[0].c.n<0)a.t[0].c.n=-a.t[0].c.n;}else if(!strcmp(name,"floor")||!strcmp(name,"ceil")||!strcmp(name,"round")){Rational r=srational(a);if(!r.d)a=sinvalid();else{int64_t q=r.n/r.d,rem=r.n%r.d;if(!strcmp(name,"floor")&&rem<0)q--;if(!strcmp(name,"ceil")&&rem>0)q++;if(!strcmp(name,"round")&&llabs(rem)*2>=r.d)q+=rem<0?-1:1;a=srat(rat(q,1));}}else a=sinvalid();}}}else p->error=1;
 p->depth--;sspace(p);while(!p->error&&*p->p=='!'){p->p++;Rational r=srational(a);if(!r.d||r.d!=1||r.n<0||r.n>14)a=sinvalid();else{Rational v=rat(1,1);for(int i=2;i<=r.n;i++)v=rop(v,rat(i,1),'*');a=srat(v);}sspace(p);}return a;}
static Symbolic sunary(SParser*);
static Symbolic spower(SParser*p){if(++p->depth>64){p->error=1;p->depth--;return sinvalid();}Symbolic a=satom(p);if(*p->p=='^'){p->p++;Rational e=srational(sunary(p));if(!e.d||e.d!=1||llabs(e.n)>40)a=sinvalid();else{Symbolic base=a;a=srat(rat(1,1));for(int i=0;i<llabs(e.n);i++)a=smul(a,base);if(e.n<0)a=sdivide(srat(rat(1,1)),a);}}p->depth--;return a;}
static Symbolic sunary(SParser*p){sspace(p);if(*p->p=='+'||*p->p=='-'){int neg=*p->p++=='-';if(++p->depth>64){p->error=1;p->depth--;return sinvalid();}Symbolic a=sunary(p);p->depth--;return neg?sscale(a,rat(-1,1)):a;}return spower(p);}
static Symbolic sproduct(SParser*p){Symbolic a=sunary(p);sspace(p);while(!p->error&&(*p->p=='*'||*p->p=='/'||*p->p=='('||isalpha((unsigned char)*p->p))){char op='*';if(*p->p=='*'||*p->p=='/')op=*p->p++;Symbolic b=sunary(p);a=op=='/'?sdivide(a,b):smul(a,b);sspace(p);}return a;}
static Symbolic ssum(SParser*p){Symbolic a=sproduct(p);sspace(p);while(!p->error&&(*p->p=='+'||*p->p=='-')){int sub=*p->p++=='-';a=sadd(a,sproduct(p),sub);sspace(p);}return a;}
static Symbolic symbolicExpression(const char*expression,Symbolic previous){SParser p={.p=expression,.budget=10000,.previous=previous};Symbolic s=ssum(&p);sspace(&p);return p.error||*p.p?sinvalid():s;}
static int symbolicText(Symbolic a,char*out,size_t size){if(a.n<0)return 0;if(!a.n){snprintf(out,size,"0");return 1;}int64_t den=1;for(int i=0;i<a.n;i++){__int128 lcm=(__int128)(den/(int64_t)rgcd(den,a.t[i].c.d))*a.t[i].c.d;if(lcm>1000000)return 0;den=(int64_t)lcm;}char terms[512]="";size_t used=0;for(int i=0;i<a.n;i++){__int128 v=(__int128)a.t[i].c.n*(den/a.t[i].c.d);if(v>1000000000000LL||v< -1000000000000LL)return 0;int64_t n=(int64_t)v;char term[96],coefficient[40];const char*sign=i?(n<0?" − ":" + "):(n<0?"−":"");if(a.t[i].rad==1)snprintf(term,sizeof(term),"%lld",(long long)llabs(n));else{if(llabs(n)==1)coefficient[0]=0;else snprintf(coefficient,sizeof(coefficient),"%lld",(long long)llabs(n));snprintf(term,sizeof(term),"%s√%lld",coefficient,(long long)a.t[i].rad);}int k=snprintf(terms+used,sizeof(terms)-used,"%s%s",sign,term);if(k<0||(size_t)k>=sizeof(terms)-used)return 0;used+=k;}int n=den==1?snprintf(out,size,"%s",terms):a.n==1?snprintf(out,size,"%s/%lld",terms,(long long)den):snprintf(out,size,"(%s)/%lld",terms,(long long)den);return n>=0&&(size_t)n<size&&n<=100;}
static void calculatorNumberText(double value,Rational rational,Symbolic symbolic,char*out,size_t size){if(fractionView&&symbolicText(symbolic,out,size))return;exactNumberText(value,rational,out,size);}
